/* Nunito variable font, SIL OFL 1.1; see docs/licenses/Nunito-OFL.txt. */
@font-face { font-family: AgentLensNunito; font-style: normal; font-weight: 200 1000; font-display: swap; src: url(data:font/woff2;base64,) format("woff2"); }
.agentlens-workbench-modal {
  --modal-width: min(1040px, calc(100vw - 80px));
  --modal-height: min(780px, calc(100vh - 80px));
  width: var(--modal-width);
  height: var(--modal-height);
  max-width: var(--modal-width);
  max-height: var(--modal-height);
}

.agentlens-workbench-modal .modal-content {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
}

.agentlens-workbench-root,
.agentlens-workbench {
  height: 100%;
  min-height: 0;
}

.agentlens-workbench {
  display: flex;
  flex-direction: column;
  color: var(--text-normal);
  background: var(--background-primary);
  font-family: var(--font-interface);
}

.agentlens-workbench__header {
  display: flex;
  align-items: center;
  justify-content: space-between; 
  gap: var(--size-4-4);
  padding: var(--size-4-5) var(--size-4-6) var(--size-4-4);
}

.agentlens-brandline,
.agentlens-account-summary {
  display: flex;
  align-items: center;
  gap: var(--size-4-3);
}

.agentlens-device-auth {
  display: flex;
  align-items: center;
  gap: var(--size-4-3);
  padding: var(--size-4-3) var(--size-4-5);
  background: var(--background-secondary);
  border-bottom: 1px solid var(--background-modifier-border);
}

.agentlens-draft-choice {
  display: flex;
  align-items: center;
  gap: var(--size-4-2);
  padding: var(--size-4-3) var(--size-4-5);
  border-block: 1px solid var(--background-modifier-border);
  background: var(--background-secondary);
}

.agentlens-draft-choice > div {
  display: grid;
  flex: 1;
  gap: var(--size-2-1);
}

.agentlens-draft-choice span {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.agentlens-account-details {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr)) auto;
  align-items: center;
  gap: var(--size-4-3);
  padding: var(--size-4-3) var(--size-4-6);
  background: var(--background-secondary);
  border-top: 1px solid var(--background-modifier-border);
  border-bottom: 1px solid var(--background-modifier-border);
}

.agentlens-account-details > div {
  display: grid;
  gap: var(--size-2-1);
}


.agentlens-device-auth > div {
  display: grid;
  gap: var(--size-2-1);
  flex: 1;
}

.agentlens-device-auth span,
.agentlens-inline-error,
.agentlens-save-result {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.agentlens-save-confirm {
  display: grid;
  gap: var(--size-4-2);
  margin-top: var(--size-4-3);
  padding: var(--size-4-3);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
  background: var(--background-primary);
}

.agentlens-save-confirm > div {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr);
  gap: var(--size-2-2);
}

.agentlens-save-confirm > .agentlens-preview-tabs {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: 100%;
}

.agentlens-save-confirm > .agentlens-preview-tabs button {
  min-width: 0;
  white-space: nowrap;
  overflow-wrap: normal;
}

.agentlens-save-confirm code {
  overflow-wrap: anywhere;
}

.agentlens-inline-error {
  color: var(--text-error);
}

.agentlens-write-plan {
  display: grid;
  gap: var(--size-4-2);
  margin: var(--size-4-4) 0;
}

.agentlens-write-plan > div {
  display: grid;
  grid-template-columns: 5rem 1fr;
  gap: var(--size-4-2);
}

.agentlens-write-plan dt {
  color: var(--text-muted);
}

.agentlens-write-plan dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}

.agentlens-bulk-toolbar {
  display: grid;
  grid-template-columns: minmax(8rem, 1fr) auto;
  gap: var(--size-4-2);
  align-items: end;
}

.agentlens-bulk-toolbar label {
  grid-column: 1 / -1;
}

.agentlens-result-list {
  display: grid;
  align-content: start;
  gap: var(--size-2-2);
  max-height: 28rem;
  overflow: auto;
}

.agentlens-bulk-filters {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--size-2-2);
}

.agentlens-bulk-filters > input:first-child,
.agentlens-bulk-filters > label:last-child {
  grid-column: 1 / -1;
}

.agentlens-bulk-filters label {
  display: grid;
  gap: var(--size-2-1);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.agentlens-selection-actions {
  display: flex !important;
  grid-template-columns: none !important;
  flex-wrap: wrap;
  gap: var(--size-2-2) !important;
  padding: 0 !important;
  border: 0 !important;
}

.agentlens-batch-manifest {
  display: grid;
  gap: var(--size-4-2);
  margin-top: var(--size-4-3);
}

.agentlens-batch-manifest > div {
  display: grid;
  grid-template-columns: 4rem 1fr;
  gap: var(--size-4-2);
}

.agentlens-batch-manifest > div > span {
  display: grid;
  min-width: 0;
  gap: var(--size-2-1);
}

.agentlens-batch-manifest small {
  color: var(--text-muted);
}

.agentlens-batch-manifest code {
  overflow-wrap: anywhere;
}

.agentlens-preview-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-2-2);
}

.agentlens-preview-tabs button[aria-selected="true"] {
  color: var(--text-on-accent);
  background: var(--interactive-accent);
}

.agentlens-markdown-preview {
  width: 100%;
  max-height: 18rem;
  margin: 0;
  overflow: auto;
  text-align: start;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.agentlens-media-plan {
  display: grid;
  width: 100%;
  gap: var(--size-2-2);
  text-align: start;
}

.agentlens-media-plan > div {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr);
  gap: var(--size-4-2);
}

.agentlens-media-plan > article {
  display: grid;
  grid-template-columns: 5rem minmax(0, 1fr);
  gap: var(--size-4-2);
  padding-block: var(--size-4-2);
  border-bottom: 1px solid var(--background-modifier-border);
}

.agentlens-media-plan > article > div {
  display: grid;
  gap: var(--size-2-1);
  min-width: 0;
}

.agentlens-media-thumb,
.agentlens-media-placeholder {
  width: 5rem;
  height: 4rem;
  object-fit: cover;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
  background: var(--background-secondary-alt);
}

/* Feedback 11: approved content inside the existing thumbnail bounds. */
.agentlens-media-placeholder-content { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; color: var(--text-faint); }
.agentlens-media-placeholder-content small { font-size: 10px; line-height: 12px; }

.agentlens-media-placeholder {
  display: grid;
  place-items: center;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.agentlens-media-placeholder > img,
.agentlens-media-thumb > img {
  width: 24px;
  height: 24px;
}

.agentlens-media-placeholder > img.agentlens-default-media-cover {
  width: 24px;
  height: 24px;
  object-fit: contain;
}

.agentlens-post-override {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--size-2-2);
  margin: var(--size-4-3) 0;
  padding: var(--size-4-3);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
}

.agentlens-post-override label {
  display: grid;
  gap: var(--size-2-1);
  min-width: 0;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.agentlens-post-override button {
  grid-column: 1 / -1;
  justify-self: start;
}

.agentlens-media-plan code {
  overflow-wrap: anywhere;
}

.agentlens-auto-layout,
.agentlens-creator-list {
  display: grid;
  gap: var(--size-4-3);
}

.agentlens-timezone-confirm,
.agentlens-follow-confirm {
  display: grid;
  grid-template-columns: minmax(12rem, 1fr) minmax(12rem, 1fr) auto;
  align-items: end;
  gap: var(--size-4-3);
  padding: var(--size-4-4);
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
}

.agentlens-timezone-confirm > div,
.agentlens-follow-form label,
.agentlens-follow-confirm label,
.agentlens-follow-confirm > div,
.agentlens-creator-list article > div {
  display: grid;
  gap: var(--size-2-1);
}

.agentlens-timezone-confirm span,
.agentlens-creator-list span {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.agentlens-follow-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--size-4-2);
  align-items: end;
}

.agentlens-creator-list {
  padding: var(--size-4-4);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
}

.agentlens-section-heading,
.agentlens-creator-list article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--size-4-3);
}

.agentlens-creator-row,
.agentlens-settings-editor {
  display: grid;
  gap: var(--size-4-3);
}

.agentlens-settings-editor {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  padding: var(--size-4-3);
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
}

.agentlens-settings-editor label {
  display: grid;
  gap: var(--size-2-1);
}

.agentlens-section-heading h3,
.agentlens-section-heading p {
  margin: 0;
}

.agentlens-creator-list article {
  padding-top: var(--size-4-3);
  border-top: 1px solid var(--background-modifier-border);
}

.agentlens-creator-trace {
  position: relative;
  display: grid !important;
  grid-template-columns: repeat(3, minmax(8rem, 1fr));
  flex: 1 1 100%;
  gap: var(--size-4-3) !important;
  padding: var(--size-4-3) var(--size-4-3) var(--size-4-3) var(--size-4-5);
  border-left: 2px solid var(--interactive-accent);
  background: var(--background-secondary);
  border-radius: 0 var(--radius-s) var(--radius-s) 0;
}

.agentlens-creator-trace > div {
  display: grid;
  gap: var(--size-2-1);
}

.agentlens-creator-trace strong {
  color: var(--text-faint);
  font-size: var(--font-ui-smaller);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.agentlens-creator-trace .is-retry {
  grid-column: 1 / -1;
  color: var(--text-warning);
}

@media (max-width: 760px) {
  .agentlens-creator-trace {
    grid-template-columns: 1fr;
  }
}

/* Logged-out workflow onboarding. The signed-in panes keep their existing layouts. */
.agentlens-onboarding {
  display: grid;
  justify-items: center;
  min-width: 0;
  min-height: 430px;
  padding: 28px 16px 24px;
  border-radius: 8px;
  background: var(--background-primary);
  text-align: center;
}

.agentlens-onboarding h3 { margin: 0; color: var(--text-normal); font-size: 20px; line-height: 28px; font-weight: 600; }
.agentlens-onboarding-description { max-width: 440px; margin: 6px 0 20px; color: var(--text-muted); font-size: 12px; line-height: 18px; }
.agentlens-onboarding-cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); width: 100%; max-width: 608px; gap: 16px; }
.agentlens-onboarding-card { min-width: 0; padding: 12px; border: 1px solid var(--background-modifier-border); border-radius: 8px; background: var(--background-secondary); text-align: left; }
.agentlens-onboarding-illustration { width: 100%; height: 93px; margin-bottom: 12px; overflow: hidden; border-radius: 6px; background: var(--background-primary); }
.agentlens-onboarding-illustration img { display: block; width: 100%; height: auto; object-fit: initial; object-position: top; }
.agentlens-onboarding-step { margin: 0 0 6px; color: var(--interactive-accent); font-size: 9px; line-height: 12px; font-weight: 700; }
.agentlens-onboarding-card h4 { margin: 0; color: var(--text-normal); font-size: 11px; line-height: 16px; font-weight: 600; }
.agentlens-onboarding-card > p:last-child { min-height: 42px; margin: 6px 0 0; color: var(--text-muted); font-size: 10px; line-height: 15px; }
.agentlens-onboarding-cta { width: 160px; min-height: 32px; margin-top: 24px; border-radius: 6px; font-size: 12px; font-weight: 600; }
.agentlens-onboarding-cta span { margin-left: 6px; font-size: 16px; line-height: 0; vertical-align: -1px; }

@media (max-width: 520px) {
  .agentlens-onboarding { padding-inline: 10px; }
  .agentlens-onboarding-cards { gap: 8px; }
  .agentlens-onboarding-card { padding: 8px; }
  .agentlens-onboarding-illustration { height: 72px; }
  .agentlens-onboarding-card h4 { font-size: 10px; }
  .agentlens-onboarding-card > p:last-child { font-size: 9px; }
}

.agentlens-brandline h1,
.agentlens-pane__intro h2,
.agentlens-preview-card h3,
.agentlens-placeholder-panel h3 {
  margin: 0;
}

.agentlens-brandline p,
.agentlens-pane__intro p,
.agentlens-preview-card p,
.agentlens-placeholder-panel p {
  margin: var(--size-2-1) 0 0;
  color: var(--text-muted);
}

.agentlens-brandmark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-m);
  color: var(--text-on-accent);
  background: var(--interactive-accent);
  font-weight: var(--font-bold);
  letter-spacing: -0.04em;
}

.agentlens-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-yellow);
}

.agentlens-tabs {
  display: flex;
  gap: var(--size-2-2);
  padding: 0 var(--size-4-6);
  border-bottom: 1px solid var(--background-modifier-border);
}

.agentlens-tabs button {
  position: relative;
  padding: var(--size-4-3) var(--size-4-3);
  color: var(--text-muted);
  background: transparent;
  border: 0;
  box-shadow: none;
}

.agentlens-tabs button.is-active {
  color: var(--text-normal);
}

.agentlens-tabs button.is-active::after {
  position: absolute;
  right: var(--size-4-3);
  bottom: -1px;
  left: var(--size-4-3);
  height: 2px;
  content: "";
  background: var(--interactive-accent);
}

.agentlens-workbench__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: var(--size-4-5) var(--size-4-6);
}

.agentlens-pane {
  display: grid;
  gap: var(--size-4-4);
}

.agentlens-update-notice {
  display: flex;
  align-items: center;
  gap: var(--size-4-3);
  padding: var(--size-4-3) var(--size-4-5);
  border-left: 3px solid var(--interactive-accent);
  background: var(--background-secondary);
}

.agentlens-update-notice.is-required {
  border-left-color: var(--text-error);
}

.agentlens-update-notice > div {
  display: grid;
  flex: 1;
  gap: var(--size-2-1);
}

.agentlens-eyebrow {
  color: var(--interactive-accent) !important;
  font-size: var(--font-ui-smaller);
  font-weight: var(--font-semibold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.agentlens-platforms {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--size-2-3);
  padding: var(--size-4-3);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
  background: var(--background-secondary);
}

.agentlens-platforms span {
  display: inline-flex;
  align-items: center;
  gap: var(--size-2-1);
  color: var(--text-muted);
}

.agentlens-platform-mark {
  display: inline-grid;
  place-items: center;
  min-width: 1.65rem;
  height: 1.65rem;
  padding-inline: var(--size-2-1);
  color: var(--text-on-accent);
  background: var(--interactive-accent);
  border-radius: var(--radius-s);
  font-size: 0.65rem;
  font-style: normal;
  font-weight: var(--font-bold);
  letter-spacing: -0.02em;
}

.agentlens-master-detail {
  display: grid;
  grid-template-columns: minmax(280px, 0.85fr) minmax(360px, 1.15fr);
  gap: var(--size-4-4);
  min-height: 300px;
}

.agentlens-source-card,
.agentlens-preview-card,
.agentlens-placeholder-panel {
  padding: var(--size-4-5);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  background: var(--background-secondary);
}

.agentlens-source-card {
  display: grid;
  align-content: start;
  gap: var(--size-4-3);
}

.agentlens-source-card > label,
.agentlens-form-grid label {
  display: grid;
  gap: var(--size-2-2);
  font-weight: var(--font-medium);
}

.agentlens-source-card input,
.agentlens-source-card select {
  width: 100%;
}

.agentlens-form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--size-4-3);
}

.agentlens-preview-card {
  display: grid;
  place-items: center;
  align-content: center;
  text-align: center;
}

.agentlens-mobile-only {
  display: none;
}

.agentlens-empty-proof {
  display: grid;
  place-items: center;
  width: 58px;
  height: 72px;
  margin-bottom: var(--size-4-3);
  border: 1px solid var(--background-modifier-border-hover);
  border-radius: var(--radius-s);
  color: var(--interactive-accent);
  background:
    linear-gradient(var(--background-modifier-border), var(--background-modifier-border)) 12px 42px / 34px 1px no-repeat,
    linear-gradient(var(--background-modifier-border), var(--background-modifier-border)) 12px 51px / 26px 1px no-repeat,
    var(--background-primary);
  font-family: var(--font-monospace);
  font-weight: var(--font-semibold);
}

.agentlens-placeholder-panel {
  min-height: 280px;
  display: grid;
  place-content: center;
  text-align: center;
}

.agentlens-evidence-trail {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--size-4-2);
  padding: var(--size-4-3) var(--size-4-6);
  border-top: 1px solid var(--background-modifier-border);
  background: var(--background-secondary);
}

.agentlens-evidence-step {
  display: flex;
  align-items: center;
  gap: var(--size-2-3);
  min-width: 0;
  color: var(--text-faint);
  font-size: var(--font-ui-smaller);
}

.agentlens-evidence-step span {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border: 1px solid var(--background-modifier-border-hover);
  border-radius: 50%;
}

.agentlens-evidence-step.is-current {
  color: var(--text-normal);
}

.agentlens-evidence-step.is-current span {
  border-color: var(--interactive-accent);
  background: var(--interactive-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--interactive-accent) 18%, transparent);
}

.agentlens-workbench :focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

@media (max-width: 760px) {
  .agentlens-workbench-modal {
    --modal-width: calc(100vw - 16px);
    --modal-height: calc(100vh - 16px);
  }

  .agentlens-workbench__header,
  .agentlens-account-summary {
    align-items: flex-start;
  }

  .agentlens-workbench__header {
    padding: var(--size-4-4);
  }

  .agentlens-device-auth {
    align-items: stretch;
    flex-direction: column;
  }

  .agentlens-draft-choice {
    align-items: stretch;
    flex-direction: column;
  }

  .agentlens-account-details {
    grid-template-columns: 1fr 1fr;
    padding-inline: var(--size-4-4);
  }

  .agentlens-bulk-toolbar {
    grid-template-columns: 1fr;
  }

  .agentlens-timezone-confirm,
  .agentlens-follow-confirm,
  .agentlens-follow-form,
  .agentlens-settings-editor,
  .agentlens-post-override,
  .agentlens-bulk-filters {
    grid-template-columns: 1fr;
  }

  .agentlens-bulk-filters > input:first-child,
  .agentlens-bulk-filters > label:last-child {
    grid-column: auto;
  }

  .agentlens-creator-list article,
  .agentlens-section-heading {
    align-items: stretch;
    flex-direction: column;
  }

  .agentlens-account-summary > span:not(.agentlens-status-dot) {
    display: none;
  }

  .agentlens-tabs,
  .agentlens-workbench__body {
    padding-right: var(--size-4-4);
    padding-left: var(--size-4-4);
  }

  .agentlens-master-detail,
  .agentlens-form-grid {
    grid-template-columns: 1fr;
  }

  .agentlens-bulk-results:not(.is-mobile-detail-open) .agentlens-preview-card,
  .agentlens-bulk-results.is-mobile-detail-open .agentlens-result-list {
    display: none;
  }

  .agentlens-mobile-only {
    display: inline-flex;
    justify-self: start;
  }

  .agentlens-evidence-trail {
    grid-template-columns: 1fr 1fr;
    padding-inline: var(--size-4-4);
  }
}

@media (prefers-reduced-motion: reduce) {
  .agentlens-workbench *,
  .agentlens-workbench *::before,
