/* Obsidian supplies native radio pseudo-elements; the Figma SVG contains both circles. */
.agentlens-single-controls input[type="radio"]::before,
.agentlens-single-controls input[type="radio"]::after { content: none; display: none; }
.agentlens-folder-field.is-compact > div > button { display: inline-flex; align-items: center; justify-content: center; padding: 0; line-height: 1; }
.agentlens-folder-field.is-compact > div > button img { display: block; }
.agentlens-save-result { overflow-wrap: anywhere; scroll-margin-top: 12px; }

/* Feedback 10: keep the approved spacing in both existing input forms. */
.agentlens-single-pane .agentlens-parse-status, .agentlens-bulk-toolbar .agentlens-parse-status { margin: 8px 0; }

/* BEGIN GENERATED AUTH HERO: src/ui/workbench/assets/auth-hero.png */
.agentlens-auth-hero { background-image: url("data:image/png;base64,"); }
/* END GENERATED AUTH HERO */

/* Keep the cover inside the existing thumbnail box in every workflow. */
.agentlens-media-placeholder { overflow: hidden; background: var(--agentlens-color-demo-surface); }
/* Center the compact prompt's close icon without a focus border. */
.agentlens-workbench .agentlens-signup-prompt > header > button { top: 2px; right: 2px; display: grid; place-items: center; padding: 10px; background: transparent; border: 0; box-shadow: none; }
.agentlens-workbench .agentlens-signup-prompt > header > button:is(:focus, :focus-visible) { outline: none; box-shadow: none; }
